import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, vec2, vec3, vec4, fract, sin, length } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const {
    Group, PlaneGeometry, Mesh, Color, DirectionalLight, SRGBColorSpace
  } = ctx.THREE;

  const colors =
    config?.intent?.visualSpec?.colors ?? config?.colors ?? {
      ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10',
    };
  const ink = colors.ink ?? '#16161d';
  const surface = colors.surface ?? '#0b0b10';
  const accent = colors.accent ?? '#ff2a38';

  const group = new Group();
  group.name = 'hub-pricing-card-2';

  // ----- Backdrop: engineered vertical gradient + grain (z=-2.5) -----
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.depthWrite = false;
  const grainUv = uv().mul(vec2(900.0, 560.0));
  const grainVal = fract(sin(grainUv.x.mul(12.9898).add(grainUv.y.mul(78.233))).mul(43758.5453));
  const grain = grainVal.sub(0.5).mul(0.02);
  backdropMat.colorNode = mix(vec3(surface), vec3(ink), uv().y).add(grain);

  const backdrop = new Mesh(new PlaneGeometry(7.0, 6.0, 1, 1), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ----- Card group (animated wrapper) -----
  const cardGroup = new Group();

  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(0x9a9aa8),
    metalness: 0.5,
    roughness: 0.55,
  });
  const card = new Mesh(new PlaneGeometry(3.0, 1.85, 4, 4), cardMat);
  card.position.set(0, 0, 0.05);
  cardGroup.add(card);

  // Accent trim line across the top of the card (signal red, frame-<=10%)
  const accentBarMat = new MeshBasicNodeMaterial({ color: new Color(accent) });
  const accentBar = new Mesh(new PlaneGeometry(3.0, 0.05, 1, 1), accentBarMat);
  accentBar.position.set(0, 0.92, 0.08);
  cardGroup.add(accentBar);

  // Subtle paper-tone plate to lift the brushed metal card on the dark stage
  const plateMat = new MeshBasicNodeMaterial({
    color: new Color(0x1a1a22),
    transparent: true,
    opacity: 0.35,
    depthWrite: false,
  });
  const plate = new Mesh(new PlaneGeometry(3.18, 2.05, 1, 1), plateMat);
  plate.position.set(0, 0, 0.03);
  cardGroup.add(plate);

  // Contact shadow under the card (radial fade)
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  const sd = uv().sub(0.5).length();
  shadowMat.colorNode = vec4(0.0, 0.0, 0.0, smoothstep(0.5, 0.0, sd).mul(0.45));
  const shadow = new Mesh(new PlaneGeometry(4.2, 1.05, 1, 1), shadowMat);
  shadow.position.set(0, -1.02, 0.02);
  shadow.rotation.x = -0.08;
  cardGroup.add(shadow);

  group.add(cardGroup);

  // ----- Local lighting (scene provides ambient 0.6 + key 1.2) -----
  const rim = new DirectionalLight(new Color(accent), 0.6);
  rim.position.set(-2.5, 1.5, 2.0);
  group.add(rim);

  const fill = new DirectionalLight(0xc3c8d4, 0.4);
  fill.position.set(2.4, 0.4, 2.0);
  group.add(fill);

  // ----- Entrance + idle motion -----
  cardGroup.position.y = 0.35;
  cardGroup.scale.setScalar(0.98);

  const tl = gsap.timeline();
  tl.to(cardGroup.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(
    cardGroup.scale,
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' },
    0
  );
  tl.to(cardGroup.scale, { x: 1.02, y: 1.02, z: 1.0, duration: 0.18, ease: 'power2.out', yoyo: true, repeat: 1 }, '>+0.05');

  const idle = gsap.to(cardGroup.scale, {
    x: 1.012, y: 1.012, z: 1.0,
    duration: 4.5, yoyo: true, repeat: -1, ease: 'sine.inOut', delay: 1.1,
  });

  // ----- Async texture load (brushed metal PBR map) -----
  let disposed = false;
  const loadUrl =
    config.imageUrl ?? '/prism-assets/chrome/brushed-metal.map.png';
  ctx.textureLoader
    .loadTexture(loadUrl)
    .then((tex) => {
      if (disposed) return;
      tex.colorSpace = SRGBColorSpace;
      if ('anisotropy' in tex) tex.anisotropy = 8;
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    })
    .catch(() => {});

  // ----- Cleanup + handlers -----
  group.userData.cleanup = () => {
    disposed = true;
    tl.kill();
    idle.kill();
    backdrop.geometry.dispose();
    backdropMat.dispose();
    card.geometry.dispose();
    cardMat.dispose();
    accentBar.geometry.dispose();
    accentBarMat.dispose();
    plate.geometry.dispose();
    plateMat.dispose();
    shadow.geometry.dispose();
    shadowMat.dispose();
  };

  group.userData.handlers = {};

  return group;
}
